room.styleText:
:host{display:block;width:100%;height:100%;min-width:0;min-height:0;color:#574530;font:16px/1.55 "Microsoft YaHei",sans-serif;color-scheme:light}
:host([hidden]){display:none}
*{box-sizing:border-box}
[hidden]{display:none!important}
button,input{font:inherit;color:inherit}
button{cursor:pointer}
button:focus-visible,input:focus-visible{outline:2px dashed #816036;outline-offset:3px}
button:disabled{cursor:default;opacity:.45}
.paper-room{position:relative;display:flex;flex-direction:column;width:100%;height:100%;min-height:0;overflow:hidden;background:#e6d5b7}
.room-toolbar{display:flex;align-items:center;justify-content:space-between;gap:16px;flex:0 0 76px;height:76px;padding:8px 28px;background:linear-gradient(#d9c3a0,#e4d2b3);z-index:2}
.room-title,.room-close,.room-phone,.room-entry-label,.room-scroll-arrow{position:relative;background:#f1e3c7;border:0;isolation:isolate;filter:drop-shadow(1px 3px 2px #76552a40)}
.room-title[data-paper],.room-close[data-paper],.room-phone[data-paper],.room-entry-label[data-paper],.room-scroll-arrow[data-paper]{background:none}
.room-title{width:220px;height:60px;margin:0;display:grid;place-items:center;font:25px/1.2 "KaiTi","STKaiti",serif;letter-spacing:2px;transform:rotate(-2deg)}
.room-toolbar-actions{display:flex;align-items:center;gap:10px}
.room-close,.room-phone{height:42px;padding:0 17px;font:20px/1.2 "KaiTi","STKaiti",serif}
.room-close{width:132px;transform:rotate(2deg)}
.room-phone{min-width:112px;transform:rotate(-1deg)}
.room-close:hover,.room-phone:hover,.room-entry-label:hover,.room-scroll-arrow:hover{filter:drop-shadow(1px 4px 3px #76552a60) brightness(1.04)}
.room-paper-crop{position:absolute;inset:0;overflow:hidden;pointer-events:none;z-index:-1}
.room-paper-image{position:absolute;display:block;max-width:none;pointer-events:none;user-select:none}
.room-paper-copy{position:relative;display:block;text-align:center;pointer-events:none;white-space:nowrap}
.room-stage{position:relative;min-height:0;min-width:0;flex:1;overflow:hidden;background:radial-gradient(ellipse at center,#e6d5b8,#d1b994)}
.room-view{position:absolute;left:0;width:100%;min-width:0;overflow-x:auto;overflow-y:hidden;overscroll-behavior-x:contain;scrollbar-width:none;touch-action:pan-y;cursor:grab;outline-offset:-3px}
.room-view::-webkit-scrollbar{display:none}
.room-view:active{cursor:grabbing}
.room-space{position:relative;flex-shrink:0;overflow:hidden}
.room-world{position:absolute;left:0;transform-origin:left top}
.room-background,.room-foreground{position:absolute;inset:0;pointer-events:none;user-select:none;max-width:none}
.room-layer{position:absolute;pointer-events:none;user-select:none;max-width:none;transform-origin:center center}
.room-helper{position:absolute;display:block;padding:0;border:0;background:none;border-radius:0;transform-origin:50% 85%;cursor:pointer;will-change:transform}
.room-helper:disabled{opacity:1;cursor:default}
.room-gramophone{position:absolute;display:block;padding:0;border:0;border-radius:0;background:transparent;transform-origin:50% 95%;transition:filter .18s ease;cursor:pointer}
.room-gramophone-card{position:absolute;inset:0;display:block;width:100%;height:100%;max-width:none;pointer-events:none;user-select:none}
.room-gramophone:hover,.room-gramophone:focus-visible{background:transparent;filter:drop-shadow(0 0 4px #fff3c8)}
.room-gramophone:focus-visible{outline:2px dashed #977140;outline-offset:1px}
.room-music-menu{position:absolute;z-index:3;isolation:isolate;pointer-events:auto;filter:drop-shadow(3px 5px 4px #62432355);background:#f2e5cb;transform:rotate(-.6deg)}
.room-music-menu[data-paper]{background:none}
.room-music-content{position:absolute;inset:0;display:flex;flex-direction:column;gap:8px;padding:15px 23px 19px}
.room-music-caption{margin:0;text-align:center;color:#8e7858;font:15px/1.2 "KaiTi","STKaiti",serif}
.room-music-choice{position:relative;isolation:isolate;flex:1;min-height:38px;padding:4px 23px;border:0;border-radius:0;background:#f6ebd2;font:20px/1.2 "KaiTi","STKaiti",serif;filter:drop-shadow(1px 2px 1px #76552a30);transition:transform .16s ease,filter .16s ease}
.room-music-choice[data-paper]{background:transparent}
.room-music-choice:hover,.room-music-choice:focus-visible{background:transparent;transform:translateY(-2px);filter:drop-shadow(1px 4px 2px #76552a45) brightness(1.03)}
.room-music-choice[aria-pressed=true]{color:#785023;font-weight:bold}
.room-music-check{position:absolute;left:12px;top:50%;transform:translateY(-50%);visibility:hidden;font-size:16px}
.room-music-choice[aria-pressed=true] .room-music-check{visibility:visible}
.room-music-menu[data-compact=true] .room-music-content{padding:9px 20px 12px;gap:3px}
.room-music-menu[data-compact=true] .room-music-choice{font-size:18px;min-height:36px}
@media(prefers-reduced-motion:reduce){.room-music-choice,.room-gramophone{transition:none}}
.room-helper:not(:disabled):hover,.room-helper:focus-visible{filter:drop-shadow(0 0 3px #ffe8ac)}
.room-helper:focus-visible{outline:2px dashed #977140;outline-offset:-10px;border-radius:20px}
.room-helper-note{position:absolute;z-index:4;isolation:isolate;margin:0;min-height:46px;display:grid;place-items:center;padding:9px 15px;background:#f4e7c9;filter:drop-shadow(2px 4px 3px #62432355);transform:rotate(-2deg);pointer-events:none;font:19px/1.4 "KaiTi","STKaiti",serif;text-align:center;color:#6a542a}
.room-helper-note[data-paper]{background:none}
.room-helper-note[data-error=true]{font-size:16px;color:#754a37;transform:rotate(1deg)}
.room-helper-note-copy{position:relative;overflow-wrap:anywhere}
.room-background{z-index:0}
.room-foreground{z-index:50}
.room-group,.room-rig,.room-person,.room-card{position:absolute;transform-origin:left top}
.room-group{z-index:20}
.room-rig,.room-person,.room-card{inset:0;width:100%;height:100%}
.room-person{padding:0;border:0;border-radius:0;background:none;outline:none}
.room-person:disabled{opacity:1;cursor:default}
.room-person:hover,.room-person:focus-visible,.room-person[aria-pressed=true]{filter:drop-shadow(0 0 3px #ffe8ac)}
.room-person:focus-visible:after{content:"";position:absolute;inset:7%;border:2px dashed #977140;border-radius:30px}
.room-card{will-change:transform;pointer-events:none}
.room-frame{position:absolute;inset:0;display:block;width:100%;height:100%;max-width:none;pointer-events:none;user-select:none}
.room-entry{position:absolute;display:block;z-index:60;background:none;border:0;padding:0;border-radius:1px;cursor:pointer}
.room-entry-supply,.room-entry-tarot{z-index:15}
.room-entry-tarot:hover,.room-entry-tarot:focus-visible{outline:2px dashed #977140;outline-offset:2px;background:#fff1c71a}
.room-entry-supply:hover,.room-entry-supply:focus-visible{outline:2px dashed #977140;outline-offset:-3px;background:#fff1c71a}
.room-entry-roster:hover,.room-entry-roster:focus-visible{background:#fff1c72b;outline:2px dashed #977140;outline-offset:0}
.room-entry-wishes:hover{box-shadow:inset 0 0 0 1px #f0e6c877}
.room-entry-wishes:focus-visible{outline:2px dashed #f1e5bf;outline-offset:-5px}
.room-chalk{position:absolute;display:flex;flex-direction:column;justify-content:center;text-align:center;white-space:nowrap;pointer-events:none;font-family:"KaiTi","STKaiti","SimSun",serif;text-shadow:0 .35px .7px #f5eed744}
.room-chalk>span{display:block}
.room-overlay{position:absolute;inset:0;z-index:5;overflow:hidden;pointer-events:none}
.room-entry-label{position:absolute;display:grid;place-items:center;padding:3px 12px;font:18px/1.15 "KaiTi","STKaiti",serif;pointer-events:auto}
.room-person-menu{position:absolute;z-index:2;isolation:isolate;pointer-events:auto;background:#f2e5cb;filter:drop-shadow(3px 5px 4px #62432355);transform:rotate(-.6deg)}
.room-person-menu[data-side=left]{transform:rotate(.6deg)}
.room-person-menu[data-paper]{background:none}
.room-menu-content{position:absolute;inset:0;display:flex;flex-direction:column;padding:13px 22px 16px;min-height:0}
.room-menu-heading{display:flex;align-items:center;justify-content:space-between;flex:0 0 25px;gap:8px;margin-bottom:2px;border-bottom:1px solid #9d7d513d}
.room-menu-name{font:20px/1.2 "KaiTi","STKaiti",serif;margin:0;letter-spacing:2px}
.room-menu-close{background:none;border:0;width:28px;height:25px;padding:0;line-height:23px;font-size:21px;color:#8a7051}
.room-menu-actions{display:flex;flex-direction:column;flex:1;min-height:0}
.room-menu-action{flex:1;min-height:0;display:block;width:100%;padding:0 3px;text-align:left;border:0;border-bottom:1px dashed #a7865640;background:transparent;font:18px/1.25 "KaiTi","STKaiti",serif;white-space:nowrap}
.room-menu-action:last-child{border-bottom:0}
.room-menu-action:before{content:"·";padding-right:8px;color:#a1845d}
.room-menu-action:hover,.room-menu-action:focus-visible{color:#75451c;background:#b3925940;outline-offset:0}
.room-slider-strip{flex:0 0 64px;height:64px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;padding:5px 26px 9px;background:linear-gradient(#dac4a1,#e9d8bc);box-shadow:inset 0 1px #b4966666}
.room-slider-label{font:16px/20px "KaiTi","STKaiti",serif;letter-spacing:2px;color:#715738;white-space:nowrap}
.room-slider-row{display:flex;align-items:center;gap:12px;width:min(800px,100%);height:30px}
.room-scroll-arrow{flex:0 0 42px;width:42px;height:27px;padding:0;font:30px/24px "KaiTi","STKaiti",serif}
.room-slider-control{position:relative;flex:1;min-width:0;height:28px}
.room-slider-rail{position:absolute;inset:4px 0;isolation:isolate;background:#b8986d}
.room-slider-rail[data-paper]{background:none;filter:drop-shadow(0 2px 1px #805e2c40)}
.room-slider-rail:after{content:"";position:absolute;left:5%;right:5%;top:50%;height:2px;background:#99764a;box-shadow:0 1px #f7edd4;pointer-events:none}
.room-slider-thumb{position:absolute;top:6px;width:40px;height:16px;transform:translateX(-50%);isolation:isolate;background:#929477;border-radius:2px;pointer-events:none;filter:drop-shadow(0 2px 1px #62472877)}
.room-slider-thumb[data-paper]{background:none;border-radius:0}
.room-slider-thumb:after{content:"";position:absolute;inset:4px 7px;background:#848b7b;border-radius:8px;box-shadow:inset 0 1px #aeb29c,0 1px #6c715a;pointer-events:none}
.room-scroll-range{position:absolute;inset:-6px 0;z-index:2;display:block;width:100%;height:40px;margin:0;padding:0;appearance:none;-webkit-appearance:none;background:transparent;cursor:ew-resize}
.room-scroll-range::-webkit-slider-runnable-track{height:28px;background:transparent;border:0}
.room-scroll-range::-webkit-slider-thumb{-webkit-appearance:none;width:40px;height:28px;background:transparent;border:0}
.room-scroll-range::-moz-range-track{height:28px;background:transparent;border:0}
.room-scroll-range::-moz-range-thumb{width:40px;height:28px;background:transparent;border:0}
.room-status{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap;border:0}
.room-status[data-error=true]{z-index:80;bottom:72px;left:50%;transform:translateX(-50%);width:min(520px,calc(100% - 28px));height:auto;margin:0;padding:10px 16px;clip-path:none;white-space:normal;background:#f2e5cb;border:1px solid #b99765;box-shadow:2px 3px 6px #62432344;font-size:14px;text-align:center}
@container (max-width:700px){.room-toolbar{height:62px;flex-basis:62px;padding:6px 15px}.room-title{width:180px;height:49px;font-size:21px}.room-toolbar-actions{gap:5px}.room-close,.room-phone{height:36px;padding:0 10px;font-size:18px}.room-close{width:104px}.room-phone{min-width:94px}.room-entry-label{font-size:16px}.room-slider-strip{padding-left:12px;padding-right:12px}.room-slider-row{gap:7px}.room-menu-content{padding:11px 17px 12px}.room-menu-name{font-size:19px}.room-menu-action{font-size:17px}}
@container (max-width:520px){.room-title{width:148px;font-size:18px}.room-close{display:none}.room-phone{min-width:92px}}
@container (max-height:500px){.room-toolbar{height:52px;flex-basis:52px;padding:3px 18px}.room-title{width:170px;height:46px;font-size:20px}.room-close,.room-phone{height:33px;font-size:17px}.room-close{width:102px}.room-phone{min-width:96px}.room-slider-strip{height:52px;flex-basis:52px;padding:3px 18px 5px;gap:0}.room-slider-label{font-size:14px;line-height:18px}.room-slider-row{height:26px}.room-menu-content{padding-top:10px;padding-bottom:11px}.room-menu-heading{flex-basis:23px}.room-menu-action{font-size:17px}}

