authority-breadcrumb{font-size:21px;color:#9a8160;line-height:1.5;margin:0 0 19px}.authority-breadcrumb button{font-size:inherit;color:inherit}.authority-breadcrumb span{margin:0 9px;color:#baa282}.authority-title{font-size:45px;line-height:1.3;font-weight:400;letter-spacing:2px;margin:0 0 24px;padding-bottom:22px;border-bottom:1px solid #b49c785e}.authority-body{font-size:24px;line-height:37px;white-space:pre-wrap;overflow-y:auto;scrollbar-width:thin;scrollbar-color:#a99570 transparent;min-height:0;flex:1;padding-right:10px}.authority-body p{margin:0 0 24px}.authority-body p:last-child{margin-bottom:0}.reading-pager{display:flex;align-items:center;justify-content:center;gap:24px;padding-top:23px;flex-shrink:0;font-size:20px;line-height:1.4;color:#958061}.reading-pager button{font-size:inherit}.back-to-profile{margin-top:auto;padding-top:25px;align-self:flex-start}.index-intro{position:absolute;left:228px;top:220px;width:532px;height:690px}.index-title{font-size:69px;letter-spacing:9px;font-weight:400;line-height:1.3;margin:25px 0 28px}.index-subtitle{font-size:25px;line-height:1.9;color:#9a815f;margin:0 0 36px}.index-current{font-size:26px;line-height:1.8;margin:44px 0 15px}.index-current small{display:block;font-size:22px;color:#a58b64}.index-count{font-size:22px;line-height:1.8;color:#a58b64;margin-top:30px}.index-intro .quiet-action{position:absolute;left:0;bottom:25px}.index-list-leaf{position:absolute;left:891px;top:200px;width:586px;height:715px;display:flex;flex-direction:column}.index-list-title{font-size:38px;font-weight:400;margin:0 0 22px;letter-spacing:3px}.index-search{display:flex;gap:12px;align-items:center;border-bottom:1px solid #a58b6577;padding-bottom:9px;flex-shrink:0}.index-search input{width:100%;min-width:0;font-size:23px;line-height:1.6;background:transparent;border:0;outline-offset:3px;padding:2px 0}.index-search input::placeholder{color:#b59d79;font-size:21px}.index-clear{font-size:20px;white-space:nowrap;color:#9b8867;padding:3px}.index-search-count{font-size:19px;color:#aa916e;margin:12px 0 10px;flex-shrink:0}.index-people{display:flex;flex-direction:column;min-height:0;flex:1}.index-person{display:flex;align-items:center;gap:22px;min-height:111px;border-bottom:1px solid #b79a7050;text-align:left;padding:16px 5px;flex-shrink:0}.index-person.is-selected{color:#63764f}.index-person-number{font-family:Georgia,serif;font-size:22px;color:#b59a75;min-width:30px}.index-person strong{display:block;font-size:31px;font-weight:400;line-height:1.3}.index-person small{display:block;font-size:20px;color:#a38964;margin-top:7px;line-height:1.3}.index-person-chevron{font-size:24px;margin-left:auto;color:#a58d68}.index-empty{font-size:25px;line-height:1.85;color:#a18a66;margin:46px 0 0}.index-empty button{font-size:21px;color:#718364;border-bottom:1px solid #9caa88;padding:3px 0;margin-top:19px}.index-pager{padding-top:21px}.index-dismiss{position:absolute;right:195px;top:151px;font-size:20px;color:#9c8866}.wish-leaf{position:absolute;left:894px;top:218px;width:567px;height:652px;overflow-y:auto;scrollbar-width:thin;scrollbar-color:#a99570 transparent}.wish-leaf h1{font-size:46px;font-weight:400;margin:0 0 36px}.wish-leaf p{font-size:24px;line-height:1.9;margin:0 0 30px}.wish-leaf .scope{font-size:20px;color:#a68c68}.visually-hidden{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
