/* 明确命中区域：书页和图卡不吞点击；覆盖正文的整面容器也不吞点击。 */
#book-layers,#bookmarks,.book-content{pointer-events:none}
.book-content>.visual-asset,.book-content>.visual-text:not(.readable-copy),.book-content>.title-rule{pointer-events:none}
.book-content>.visual-control,.book-content>.note-tab,.book-content>.readable-copy,.book-content>.relation-picker,.book-content>.reading-leaf,.book-content>.wish-leaf{pointer-events:auto}
.book-content>.book-index{pointer-events:none}.book-index button,.book-index input,.book-index .index-people{pointer-events:auto}
.bookmark-art,.bookmark-art img{pointer-events:none}.bookmark-hit{pointer-events:auto}
.readable-copy,.authority-body{overscroll-behavior:contain}
.book-index>.index-piece{position:absolute;margin:0;white-space:pre-wrap}
.index-back{text-align:left}.index-current-caption{color:#a58b64}
.index-people{overflow-y:auto;overflow-x:hidden;scrollbar-width:thin;scrollbar-color:#a99570 transparent}
.index-people .index-person{position:relative;display:block;flex-grow:0;flex-shrink:0;width:100%;padding:0;overflow:hidden}
