:host{display:block;width:100%;height:100%;min-width:0;min-height:0;color-scheme:dark;font-family:"KaiTi","STKaiti","SimSun",serif;color:#f1ead5;background:#d6cbb8;font-synthesis:none;--chalk:#f1ead5;--quiet:#c9cdb9;--soft:#aab39e;--ink:#624f39}
