.chalk-line{position:absolute;pointer-events:none;transform-origin:left top;z-index:5}.paper-tape{position:absolute;z-index:25;pointer-events:none;background:#d3bb8ba8;clip-path:polygon(0 3%,97% 0,100% 14%,97% 28%,100% 44%,97% 60%,100% 76%,98% 100%,2% 97%,0 82%,3% 63%,0 47%,3% 29%)}
