.tk-void-card{position:relative;display:block;width:100%;container-type:inline-size;font-family:"SimSun","Songti SC","Noto Serif CJK SC",serif;color:var(--vc-ink);text-align:left;line-height:1.7;color-scheme:dark;isolation:isolate}
