.tk-void-canvas{position:relative;aspect-ratio:1672/941;overflow:hidden;background:var(--vc-base);font-size:clamp(13px,1.3cqw,23px)}
.tk-void-plane,.tk-void-frame{position:absolute;inset:0;pointer-events:none}.tk-void-plane{background:var(--vc-texture) center/100% 100%,var(--vc-base)}.tk-void-frame{background:var(--vc-frame) center/100% 100% no-repeat}
