.tk-void-origin{text-align:center;min-width:0;padding-top:3cqw}.tk-void-eyebrow,.tk-void-quote-label{font-size:clamp(12px,1.15cqw,20px);color:var(--vc-light)!important}.tk-void-origin h2{font-size:clamp(20px,3.05cqw,52px);line-height:1.3;margin:.5cqw 0 1cqw}
.tk-void-seal{display:block;position:relative;width:100%;aspect-ratio:1.1;margin:.6cqw auto;background:var(--vc-seal) center/contain no-repeat}
.tk-void-star{position:absolute;left:var(--x);top:var(--y);width:10%;aspect-ratio:1;transform:translate(-50%,-50%);animation:tk-void-twinkle var(--duration) ease-in-out var(--delay) infinite;filter:drop-shadow(0 0 4px var(--vc-glow));background:radial-gradient(ellipse,#fff 0 7%,var(--vc-light) 15%,transparent 64%)}
.tk-void-star:before,.tk-void-star:after{content:"";position:absolute;inset:43% 0;background:linear-gradient(90deg,transparent,#fff,transparent)}.tk-void-star:after{inset:0 44%;background:linear-gradient(transparent,#fff,transparent)}
@keyframes tk-void-twinkle{0%,100%{opacity:.18;scale:.78}45%{opacity:1;scale:1.2}65%{opacity:.5;scale:.96}}
.tk-void-prototype{font-size:clamp(12px,1.2cqw,21px);color:var(--vc-light)!important;margin:.8cqw 0!important}
.tk-void-rule{position:relative;height:1px;margin:1.2cqw 0;background:linear-gradient(90deg,transparent,var(--vc-light),#ebf4ff,var(--vc-light),transparent)}.tk-void-rule:after{content:"✦";position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);font-size:1.15cqw;color:#fff;text-shadow:0 0 .6cqw var(--vc-glow)}
.tk-void-origin blockquote{font-size:clamp(12px,1.25cqw,22px);line-height:1.9;margin:.6cqw 0}.tk-void-origin cite{display:block;font-size:clamp(11px,1.05cqw,18px);color:var(--vc-light);margin-top:.7cqw}
.tk-void-body{min-width:0}.tk-void-title{text-align:center}.tk-void-title>p{font-size:clamp(12px,1.15cqw,20px);color:var(--vc-light);letter-spacing:.18em}.tk-void-title>h2{font-size:clamp(24px,2.8cqw,48px);font-weight:600;line-height:1.4;margin:.55cqw 0;letter-spacing:.065em;text-shadow:0 0 .65cqw color-mix(in srgb,var(--vc-light) 35%,transparent)}.tk-void-title>.tk-void-native-name{font-size:clamp(13px,1.4cqw,25px);letter-spacing:.1em}.tk-void-title>.tk-void-name-meaning{font-size:clamp(11px,1cqw,18px);letter-spacing:.06em;opacity:.8}
.tk-void-meta{display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:.5cqw 1cqw;color:var(--vc-light);margin:.8cqw 0;font-size:clamp(12px,1.2cqw,21px)}.tk-void-meta strong{font-size:clamp(14px,1.5cqw,27px);font-weight:400}
.tk-void-verdict{margin:1.1cqw 0 1.5cqw}.tk-void-verdict h3,.tk-void-cost-copy h3{font-size:clamp(14px,1.35cqw,24px);color:var(--vc-light);margin-bottom:.5cqw}.tk-void-verdict p{font-size:clamp(14px,1.4cqw,25px);line-height:1.9}
.tk-void-skill{margin:0 0 1cqw;padding:1.1cqw 1.5cqw;border-image:var(--vc-row) 12 40 fill / .7cqw 2.5cqw / 0 stretch;background:color-mix(in srgb,var(--vc-base) 70%,transparent)}
.tk-void-skill h3{display:flex;gap:.8cqw;align-items:baseline;font-size:clamp(16px,1.6cqw,28px);margin:0 0 .55cqw;letter-spacing:.035em}.tk-void-numeral{color:var(--vc-light);font-size:.85em}.tk-void-skill h3 small{margin-left:auto;white-space:nowrap;color:var(--vc-light);font-size:.65em}.tk-void-skill p{font-size:clamp(13px,1.3cqw,23px);line-height:1.85}.tk-void-release{padding:1.4cqw 1.8cqw;border-image-source:var(--vc-release);border-image-slice:24 52;border-image-width:1.4cqw 3.2cqw}.tk-void-release .tk-void-power{color:var(--vc-light);font-size:clamp(12px,1.1cqw,20px);margin:.5cqw 0}
.tk-void-cost{margin:.6cqw 0 1cqw}.tk-void-cost>summary{list-style:none}.tk-void-cost>summary::-webkit-details-marker{display:none}.tk-void-cost>summary i{display:inline-block;font-style:normal;transition:transform .2s}.tk-void-cost[open]>summary i{transform:rotate(180deg)}.tk-void-cost-copy{padding:1cqw 1.4cqw;margin-top:.6cqw;background:color-mix(in srgb,var(--vc-base) 88%,var(--vc-glow));border-inline-start:1px solid var(--vc-light)}.tk-void-cost-copy p{line-height:1.9;margin-bottom:1cqw}
.tk-void-footer{position:absolute;left:35%;right:11%;bottom:7%;min-height:5.5cqw;display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:.3cqw 1cqw}.tk-void-location{font-size:clamp(11px,1cqw,18px);color:var(--vc-light)}.tk-void-footer>div{display:flex;gap:.5cqw;align-items:center;margin-left:auto}
.tk-void-card .tk-void-button,.tk-void-card .tk-void-tool{appearance:none;border:0;border-radius:0;color:var(--vc-ink);box-shadow:none;background-color:transparent;padding:0;font:inherit;cursor:pointer;position:relative;transition:transform .2s ease,filter .2s ease;display:grid;place-items:center;text-align:center;min-width:0;line-height:1.25;isolation:isolate}
.tk-void-card .tk-void-button{width:14.5cqw;min-width:94px;height:4.4cqw;min-height:32px;font-size:clamp(12px,1.35cqw,24px);white-space:nowrap;background:var(--vc-secondary) center/100% 100% no-repeat;clip-path:polygon(10% 0,90% 0,100% 50%,90% 100%,10% 100%,0 50%)}.tk-void-card .tk-void-primary{background-image:var(--vc-primary)}.tk-void-button>span{padding:0 1cqw;text-shadow:0 0 .3cqw var(--vc-glow)}
.tk-void-card .tk-void-button:hover,.tk-void-card .tk-void-tool:hover{transform:translateY(-.2cqw);filter:brightness(1.25) drop-shadow(0 .08cqw .3cqw var(--vc-glow));background-color:transparent;box-shadow:none}.tk-void-card .tk-void-button:active,.tk-void-card .tk-void-tool:active{transform:translateY(0)}.tk-void-card :is(button,summary):focus-visible{filter:brightness(1.35) drop-shadow(0 0 4px var(--vc-light));outline:0}
.tk-void-tools{position:absolute;right:1.2%;top:2.2%;display:flex;gap:.35cqw}.tk-void-card .tk-void-tool{width:4.5cqw;height:4.65cqw;min-width:28px;min-height:28px;background:var(--vc-close) center/contain no-repeat;clip-path:polygon(50% 0,84% 16%,100% 50%,84% 84%,50% 100%,16% 84%,0 50%,16% 16%)}.tk-void-card .tk-void-music{background-image:var(--vc-music)}.tk-void-music[aria-pressed=false]:after{content:"";width:45%;height:1px;background:#fff;transform:rotate(-50deg);box-shadow:0 0 3px #000}
