.tk-void-reveal{display:block;margin:1.2em 0;max-width:1672px;font-family:"SimSun","Songti SC",serif;color:#edf1ff}.tk-void-reveal>summary{position:relative;display:flex;min-height:110px;flex-direction:column;align-items:center;justify-content:center;list-style:none;cursor:pointer;gap:8px;background:radial-gradient(ellipse,#5785ca23,transparent 70%);border:0}.tk-void-reveal>summary::-webkit-details-marker{display:none}.tk-void-reveal>summary>span:not(.tk-void-reveal-line){font-size:24px;letter-spacing:.25em;text-shadow:0 0 12px #b5d3ff;transition:transform .2s}.tk-void-reveal>summary small{color:#b7c9e7;font-size:14px;letter-spacing:.12em}.tk-void-reveal-line{display:block;width:72%;height:1px;background:linear-gradient(90deg,transparent,#9fc7ff,#fff,#9fc7ff,transparent);box-shadow:0 0 10px #b8d8ff;margin-bottom:10px}.tk-void-reveal>summary:hover>span:not(.tk-void-reveal-line){transform:translateY(-3px)}.tk-void-reveal[open]>summary{min-height:54px}.tk-void-reveal[open]>summary>span:not(.tk-void-reveal-line){font-size:16px}.tk-void-reveal[open]>summary small,.tk-void-reveal[open] .tk-void-reveal-line{display:none}.tk-void-reveal[open]>.tk-void-card{animation:tk-void-unveil .7s ease-out both}
