carolyn.studioStyleText:
.carolyn-studio .conversation-caption{position:absolute;left:99px;top:85px;font-size:23px;line-height:35px;color:#5f7196;max-width:640px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.carolyn-studio .spoken-answer{white-space:pre-wrap}
.carolyn-studio .listening{font-size:22px;color:#657ca4}
.carolyn-studio .work-top>.talk-target{display:flex;align-items:center;justify-content:center;flex:none;width:295px;height:61px;padding:8px 20px;background:var(--art-role-select-blank) center/100% 100% no-repeat;font-size:25px;font-weight:700;line-height:1.3;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.carolyn-studio .source-selector select{font-size:23px}
.carolyn-studio .work-heading{max-width:280px}
.carolyn-studio .work-scroll .appraisal{font-size:23px;line-height:1.7;margin:0 2px 12px}
.carolyn-studio .quiet-soul{display:flex;flex-direction:column;justify-content:center;align-items:center;min-height:217px;text-align:center;color:#657aa3}
.quiet-soul>span{font-size:49px;line-height:1.2;color:#7288b8}
.quiet-soul>p{font-size:24px;line-height:1.9}
.carolyn-studio .tendency{min-height:94px;font-size:22px}
.carolyn-studio .tendency>.button-face{padding:12px 22px}
.carolyn-studio .tendency strong,.carolyn-studio .tendency span:not(.button-face){display:block}
.carolyn-studio .tendency span:not(.button-face){font-size:19px;margin-top:3px}
.carolyn-studio .quiet-note{width:221px;text-align:center;font-size:21px;color:#7c87a2}
.carolyn-studio .delivery-switch{position:absolute;right:79px;top:182px;display:block;width:170px;height:36px;margin:0;padding:0;z-index:4}
.delivery-switch select{position:absolute;inset:0;width:100%;height:100%;margin:0;padding:0;border:0;opacity:0;cursor:pointer}
.delivery-face{display:flex;align-items:center;justify-content:center;gap:10px;width:100%;height:100%;padding:0 13px;background:var(--art-save-draft-blank) center/100% 100% no-repeat;color:#293f7c;font:19px/1.2 'SimSun','Songti SC',serif;white-space:nowrap;pointer-events:none;transition:transform .18s ease,filter .18s ease}
.delivery-face::after{content:'';flex:none;width:13px;height:12px;background:var(--art-down-chevron) center/contain no-repeat}
.delivery-switch select:hover:not(:disabled)+.delivery-face{transform:translateY(-4px);filter:drop-shadow(0 5px 3px #132c5944)}
.delivery-switch select:focus-visible+.delivery-face{filter:drop-shadow(0 0 3px #769bea)}
.delivery-switch option{background:#f7f5ee;color:#21346d}
.carolyn-studio .notebook .scope-badge{right:145px}
.carolyn-studio .notebook .fp{max-width:140px;overflow:hidden}
.carolyn-studio .empty-copy .facts dd{max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.carolyn-studio .empty-copy{font-size:22px}
.carolyn-studio .empty-copy small{font-size:19px}
.carolyn-studio .owned-soul h3{margin:8px 0;font-size:29px}
.carolyn-studio .unavailable-copy{font-size:23px;line-height:1.7}
.carolyn-studio .work-scroll .hint{font-size:20px}
.carolyn-studio .card-detail button[data-action=transfer]:not(.tk-void-button){width:170px;height:56px}
.carolyn-studio .card-detail .context-sheet{max-width:100%;width:100%}
@media(prefers-reduced-motion:reduce){.delivery-face{transition:none}}
.carolyn-studio button.music-toggle{position:absolute;right:26px;top:0;width:270px;height:90px;font-size:24px;z-index:5}
.carolyn-studio .music-toggle>.button-face{padding:0 29px 7px 75px;gap:0;background-image:var(--art-music-toggle)}
.carolyn-studio .music-label{line-height:1.2;letter-spacing:1px;color:#263d78;text-shadow:0 1px 0 #fff}
.carolyn-studio .music-toggle[data-music-state=off]>.button-face{filter:saturate(.55)}
.carolyn-studio .music-toggle[data-music-state=off] .music-label{color:#7884a1}
